cd /workspace && cat > sitecustomize.py <<'PY'
import os
import subprocess
_original_popen = subprocess.Popen
def _popen(*args, **kwargs):
    kwargs['start_new_session'] = False
    return _original_popen(*args, **kwargs)
subprocess.Popen = _popen
_original_killpg = os.killpg
def _killpg(pid, sig):
    try:
        return _original_killpg(pid, sig)
    except PermissionError:
        try:
            os.kill(pid, sig)
        except ProcessLookupError:
            pass
os.killpg = _killpg
PY
python3 - <<'PY'
import subprocess
print(subprocess.Popen is __import__('sitecustomize')._original_popen)
PY
rm -f sitecustomize.py
ls sitecustomize.py 2>&1 || true
